#!/usr/bin/env python3
"""Render agent/oncall-agent.src.yaml into the self-contained dist/oncall-agent.yaml.

Docker Agent's OCI artifact (docker agent share push) carries one config file, so prompts
and skills are inlined here instead of being referenced as separate files.
"""
from __future__ import annotations

import argparse
import re
import sys
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parents[1]
AGENT = ROOT / "agent"
SRC = AGENT / "oncall-agent.src.yaml"
OUT = ROOT / "dist" / "oncall-agent.yaml"
HEADER = (
    "# GENERATED by scripts/build_agent.py from agent/oncall-agent.src.yaml - do not edit.\n"
    "# yaml-language-server: $schema=https://raw.githubusercontent.com/docker/docker-agent/main/agent-schema.json\n"
)


def parse_skill(name: str) -> dict:
    path = AGENT / "skills" / name / "SKILL.md"
    text = path.read_text()
    m = re.match(r"^---\n(.*?)\n---\n(.*)$", text, re.S)
    if not m:
        raise SystemExit(f"{path}: missing YAML frontmatter")
    front = yaml.safe_load(m.group(1))
    if front.get("name") != name:
        raise SystemExit(f"{path}: frontmatter name {front.get('name')!r} != directory {name!r}")
    return {"name": name, "description": front["description"], "instructions": m.group(2).strip() + "\n"}


def render(node, version: str):
    if isinstance(node, dict):
        return {k: render(v, version) for k, v in node.items()}
    if isinstance(node, list):
        return [render(v, version) for v in node]
    if isinstance(node, str):
        if node.startswith("@include "):
            return (AGENT / node[len("@include "):].strip()).read_text()
        if node.startswith("@skill "):
            return parse_skill(node[len("@skill "):].strip())
        if node == "@version":
            return version
    return node


class _Dumper(yaml.SafeDumper):
    pass


def _str(dumper, data):
    style = "|" if "\n" in data else None
    return dumper.represent_scalar("tag:yaml.org,2002:str", data, style=style)


_Dumper.add_representer(str, _str)


def build() -> str:
    version = (ROOT / "VERSION").read_text().strip()
    doc = render(yaml.safe_load(SRC.read_text()), version)
    return HEADER + yaml.dump(doc, Dumper=_Dumper, sort_keys=False, width=110, allow_unicode=True)


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--check", action="store_true", help="fail if dist/ is out of date")
    args = ap.parse_args()
    out = build()
    if args.check:
        if not OUT.exists() or OUT.read_text() != out:
            print("dist/oncall-agent.yaml is out of date; run scripts/build.sh", file=sys.stderr)
            return 1
        print("dist/oncall-agent.yaml is up to date")
        return 0
    OUT.parent.mkdir(exist_ok=True)
    OUT.write_text(out)
    print(f"wrote {OUT.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
